$ErrorActionPreference = 'Stop'
try {
node 'C:\Users\Test Home\pinokio\api\Astrid O''Malley\pinokio\shell.mjs' 'C:\Users\Test Home\pinokio\api\Astrid O''Malley' '$ErrorActionPreference = ''Stop''
$version = (Get-Content -Raw -LiteralPath ''C:\Users\Test Home\pinokio\api\Astrid O''''Malley\app\astrid\current'').Trim()
if ($version -notmatch ''^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'') { throw ''Invalid Astrid version pointer.'' }
$versionRoot = Join-Path ''C:\Users\Test Home\pinokio\api\Astrid O''''Malley\app\astrid\versions'' $version
$record = Get-Content -Raw -LiteralPath (Join-Path $versionRoot ''version.json'') | ConvertFrom-Json
$node = [IO.Path]::GetFullPath([string]$record.env.ASTRID_NODE_EXECUTABLE)
$prefix = [IO.Path]::GetFullPath($versionRoot) + [IO.Path]::DirectorySeparatorChar
if (-not $node.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase)) { throw ''Pinned Node is outside the installed version.'' }
& $node ''C:\Users\Test Home\pinokio\api\Astrid O''''Malley\pinokio\session.mjs'' ''build'' ''C:\Users\Test Home\pinokio\api\Astrid O''''Malley\app\astrid'' ''C:\Users\Test Home\pinokio\api\Astrid O''''Malley\app\editor'' ''local''
if ($LASTEXITCODE -ne 0) { throw ''Astrid process failed.'' }' '{"ASTRID_INSTALL_MANAGED_BY":"pinokio"}'
if ($LASTEXITCODE -ne 0) { throw 'Astrid process failed.' }
} catch {
Write-Output ('ASTRID_PINOKIO_' + 'FAILURE')
throw
}
}

